const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const title = data.meetingTitle || data.title || 'Untitled Meeting';
  const attendees = data.attendees || [];
  const agenda = data.agenda || [];
  const date = data.startTime || new Date().toISOString();
  const duration = data.duration || 'N/A';

  const attendeeList = Array.isArray(attendees)
    ? attendees.map(a => typeof a === 'string' ? a : a.email || a.name).join(', ')
    : String(attendees);

  const agendaItems = Array.isArray(agenda)
    ? agenda.map((a, i) => `${i + 1}. ${typeof a === 'string' ? a : a.topic || a}`).join('\n')
    : String(agenda);

  return {
    json: {
      title: title,
      attendees: attendeeList,
      agenda: agendaItems,
      date: date,
      duration: duration,
      notesTemplate: `## Attendees\n${attendeeList}\n\n## Agenda\n${agendaItems}\n\n## Discussion Notes\n- \n\n## Action Items\n- [ ] \n\n## Decisions Made\n- \n\n## Next Steps\n- `
    }
  };
});

